import com.pv.cases.model.*;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;
import tools.jackson.databind.json.JsonMapper;

public class RoundTrip {
	public static void main(String[] args) throws Exception {
		JsonMapper m = JsonMapper.builder().build();

		// 1. Deserialize the seed file into CaseDocument.
		String seed = Files.readString(Path.of(
				"/Users/sadikshaikh/project/pv-case-processing/backend/src/main/resources/case_v1.json"));
		CaseDocument doc = m.readValue(seed, CaseDocument.class);
		System.out.println("caseId=" + doc.caseId() + " version=" + doc.version()
				+ " extractedAt=" + doc.extractedAt() + " classification=" + doc.caseClassification()
				+ " sourceDoc=" + doc.sourceDocument());
		System.out.println("sections=" + doc.sections().keySet());
		System.out.println("patient fields (order)=" + doc.sections().get("patient").keySet());
		System.out.println("age=" + doc.sections().get("patient").get("age"));
		System.out.println("missingFields=" + doc.missingFields());

		// 2. Re-serialize and confirm snake_case survives.
		String out = m.writerWithDefaultPrettyPrinter().writeValueAsString(doc);
		System.out.println("--- reserialized head ---");
		System.out.println(out.substring(0, Math.min(340, out.length())));

		// 3. missing_fields on an inbound follow-up payload.
		String followUp = """
				{"case_id":"PV-2026-0451","version":2,"case_classification":"significant",
				 "extracted_at":"2026-05-01T10:00:00Z","source_document":"followup.pdf",
				 "missing_fields":["adverse_event.onset_date"],
				 "sections":{"patient":{"age":{"value":"63","confidence":0.95,"source":"p.1 §2"}}}}""";
		CaseDocument fu = m.readValue(followUp, CaseDocument.class);
		System.out.println("followup missingFields=" + fu.missingFields());

		// 4. Defensive copy: stored doc must not be mutable through its map.
		try {
			doc.sections().get("patient").put("age", null);
			System.out.println("MUTABLE — defensive copy FAILED");
		} catch (UnsupportedOperationException e) {
			System.out.println("defensive copy OK (sections unmodifiable)");
		}

		// 5. MergedField statuses + the previousValue invariant.
		FieldValue oldAge = doc.sections().get("patient").get("age");
		FieldValue newAge = fu.sections().get("patient").get("age");
		System.out.println(m.writeValueAsString(MergedField.overridden(newAge, oldAge)));
		System.out.println(m.writeValueAsString(MergedField.unchanged(oldAge)));
		System.out.println(m.writeValueAsString(MergedField.retained(oldAge)));
		try {
			new MergedField("x", 0.5, "p.1", FieldStatus.NEW, oldAge);
			System.out.println("invariant NOT enforced");
		} catch (IllegalArgumentException e) {
			System.out.println("invariant OK: " + e.getMessage());
		}

		// 6. FieldStatus wire names round-trip.
		System.out.println("statuses=" + m.writeValueAsString(FieldStatus.values())
				+ " parsed=" + m.readValue("\"new\"", FieldStatus.class));

		// 7. MergedCase, including nested MergeSummary with the "new" key.
		Map<String, Map<String, MergedField>> sections = new LinkedHashMap<>();
		sections.put("patient", new LinkedHashMap<>(Map.of("age", MergedField.overridden(newAge, oldAge))));
		MergedCase merged = new MergedCase("PV-2026-0451", 2, 1, 2, "significant",
				Instant.parse("2026-05-01T10:05:00Z"),
				List.of("initial_report_PV-2026-0451.pdf", "followup.pdf"),
				sections, List.of("adverse_event.onset_date"),
				new MergedCase.MergeSummary(9, 1, 0, 4));
		System.out.println("--- MergedCase ---");
		System.out.println(m.writerWithDefaultPrettyPrinter().writeValueAsString(merged));
		System.out.println("summary.total=" + merged.summary().total());

		// 8. Query.
		Query q = Query.create("PV-2026-0451", "patient.age", "Age conflicts with the narrative — confirm?");
		System.out.println("--- Query ---");
		System.out.println(m.writeValueAsString(q));
		System.out.println("section=" + q.sectionName() + " field=" + q.fieldName());
		System.out.println("query round-trip=" + m.readValue(m.writeValueAsString(q), Query.class).equals(q));
	}
}

