import com.pv.cases.model.*;
import jakarta.validation.*;
import java.util.*;

public class ValidCheck {
	public static void main(String[] args) {
		Validator v;
		try (ValidatorFactory f = Validation.buildDefaultValidatorFactory()) {
			v = f.getValidator();

			// A bad FieldValue buried two map levels deep: confidence out of range, blank source.
			Map<String, Map<String, FieldValue>> sections = new LinkedHashMap<>();
			sections.put("patient", new LinkedHashMap<>(Map.of(
					"age", new FieldValue("62", 1.7, "  "))));
			CaseDocument doc = new CaseDocument("PV-1", 1, "x", null, "d.pdf", sections, null);
			System.out.println("nested cascade violations:");
			v.validate(doc).forEach(c -> System.out.println("  " + c.getPropertyPath() + " -> " + c.getMessage()));

			// Top-level constraints.
			CaseDocument bad = new CaseDocument("  ", 0, null, null, null, null, null);
			System.out.println("top-level violations:");
			v.validate(bad).forEach(c -> System.out.println("  " + c.getPropertyPath() + " -> " + c.getMessage()));

			// Query fieldPath pattern.
			System.out.println("query violations:");
			v.validate(new Query(null, "PV-1", "patientage", "why?", null))
					.forEach(c -> System.out.println("  " + c.getPropertyPath() + " -> " + c.getMessage()));
			System.out.println("valid query violations=" + v.validate(Query.create("PV-1", "patient.age", "why?")).size());
		}
	}
}

