import com.pv.cases.config.StartupDataLoader;
import com.pv.cases.repository.InMemoryCaseStore;
import tools.jackson.databind.json.JsonMapper;

/** Drives StartupDataLoader against a classpath whose seed resource is missing/corrupt/mismatched. */
public class SeedFailure {
	public static void main(String[] args) {
		InMemoryCaseStore store = new InMemoryCaseStore();
		StartupDataLoader loader = new StartupDataLoader(store, JsonMapper.builder().build());
		try {
			loader.run(null);
			System.out.println("!! startup SUCCEEDED — caseCount=" + store.caseCount());
		}
		catch (IllegalStateException e) {
			System.out.println("IllegalStateException: " + e.getMessage());
			if (e.getCause() != null) {
				String cause = e.getCause().toString();
				System.out.println("  cause: " + cause.substring(0, Math.min(110, cause.length())).replace('\n', ' '));
			}
			System.out.println("  store left empty: " + (store.caseCount() == 0));
		}
	}
}

