import com.pv.cases.model.*;
import com.pv.cases.service.MergeService;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;
import tools.jackson.databind.json.JsonMapper;

/** Merges a realistic follow-up into the real seed case and prints the result. */
public class MergeDemo {
	public static void main(String[] args) throws Exception {
		JsonMapper m = JsonMapper.builder().build();
		CaseDocument stored = m.readValue(Files.readString(Path.of(
				"/Users/sadikshaikh/project/pv-case-processing/backend/src/main/resources/case_v1.json")),
				CaseDocument.class);

		// A plausible follow-up: age corrected, seriousness escalated, confidence
		// nudged on an unchanged field, a new lab section, reporter section absent.
		String followUpJson = """
				{
				  "case_id": "PV-2026-0451",
				  "version": 2,
				  "case_classification": "significant",
				  "extracted_at": "2026-05-02T11:20:00Z",
				  "source_document": "followup_PV-2026-0451.pdf",
				  "missing_fields": ["patient.weight_kg"],
				  "sections": {
				    "patient": {
				      "initials": { "value": "M.K.", "confidence": 0.99, "source": "p.1 §1" },
				      "age": { "value": "63", "confidence": 0.96, "source": "p.1 §2" },
				      "sex": { "value": "Male", "confidence": 0.99, "source": "p.1 §1" }
				    },
				    "adverse_event": {
				      "event_term": { "value": "Rhabdomyolysis", "confidence": 0.92, "source": "p.2 §1" },
				      "onset_date": { "value": "2026-03-12", "confidence": 0.88, "source": "p.2 §1" },
				      "outcome": { "value": "Recovering", "confidence": 0.77, "source": "p.3 §1" },
				      "seriousness": { "value": "Serious", "confidence": 0.94, "source": "p.3 §1" }
				    },
				    "lab_results": {
				      "creatine_kinase": { "value": "8200 U/L", "confidence": 0.91, "source": "p.4 §2" }
				    }
				  }
				}""";
		CaseDocument followUp = m.readValue(followUpJson, CaseDocument.class);

		MergedCase merged = new MergeService().merge(stored, followUp);

		System.out.println("sections in order: " + merged.sections().keySet());
		System.out.println();
		merged.sections().forEach((section, fields) -> fields.forEach((name, f) -> System.out.printf(
				"  %-14s %-16s %-11s %-14s conf=%.2f%s%n", section, name, f.status().wireName(),
				"\"" + f.value() + "\"", f.confidence(),
				f.previousValue() == null ? "" : "   was \"" + f.previousValue().value() + "\" conf="
						+ f.previousValue().confidence() + " @ " + f.previousValue().source())));

		System.out.println();
		System.out.println("summary: " + m.writeValueAsString(merged.summary())
				+ "  total=" + merged.summary().total());
		System.out.println("versions: base=" + merged.baseVersion() + " incoming=" + merged.incomingVersion()
				+ " result=" + merged.version());
		System.out.println("classification: " + stored.caseClassification() + " -> " + merged.caseClassification());
		System.out.println("sourceDocuments: " + merged.sourceDocuments());
		System.out.println("missingFields: " + merged.missingFields());
	}
}

