import com.pv.cases.exception.*;
import java.lang.reflect.Constructor;
import org.springframework.core.MethodParameter;
import org.springframework.http.ResponseEntity;
import org.springframework.validation.BeanPropertyBindingResult;
import org.springframework.validation.BindingResult;
import org.springframework.web.bind.MethodArgumentNotValidException;
import tools.jackson.databind.json.JsonMapper;

/** Serializes each handler's response body exactly as the framework would. */
public class ErrorBodies {
	public static void main(String[] args) throws Exception {
		JsonMapper m = JsonMapper.builder().build();
		GlobalExceptionHandler handler = new GlobalExceptionHandler();

		ResponseEntity<?> notFound = handler.handleCaseNotFound(new CaseNotFoundException("PV-2026-0451"));
		System.out.println("404 status=" + notFound.getStatusCode().value());
		System.out.println("404 body=" + m.writeValueAsString(notFound.getBody()));

		// Build a real MethodArgumentNotValidException with two field errors.
		BindingResult binding = new BeanPropertyBindingResult(new Object(), "query");
		binding.rejectValue(null, "NotBlank", "must not be blank");
		binding.addError(new org.springframework.validation.FieldError(
				"query", "question", null, false, new String[] { "NotBlank" }, null, "must not be blank"));
		binding.addError(new org.springframework.validation.FieldError(
				"query", "fieldPath", "patientage", false, new String[] { "Pattern" }, null,
				"must be a dot-separated section and field, e.g. patient.age"));
		Constructor<MethodArgumentNotValidException> ctor = MethodArgumentNotValidException.class
				.getConstructor(MethodParameter.class, BindingResult.class);
		MethodParameter param = new MethodParameter(ErrorBodies.class.getDeclaredMethod("stub", String.class), 0);
		ResponseEntity<?> invalid = handler.handleValidationFailure(ctor.newInstance(param, binding));
		System.out.println("400 status=" + invalid.getStatusCode().value());
		System.out.println("400 body=" + m.writeValueAsString(invalid.getBody()));

		ResponseEntity<?> boom = handler.handleUnexpected(new IllegalStateException("merge blew up"));
		System.out.println("500 status=" + boom.getStatusCode().value());
		System.out.println("500 body=" + m.writeValueAsString(boom.getBody()));
	}

	@SuppressWarnings("unused")
	private static void stub(String question) {
	}
}

